    };

    // Imbalance penalties with adaptive scaling based on resource usage and increased penalty for high imbalance
    let cpu_penalty = if cpu_norm > 1.5 { (cpu_norm - 1.5).powi(2) * 3.0 } else { 0.0 };
    let ram_penalty = if ram_norm > 1.5 { (ram_norm - 1.5).powi(2) * 3.0 } else { 0.0 };

    // Balance CPU and RAM usage with increased weight for balance factor
    let balance_factor = ((node_residual_cpu as f64 / node_capacity_cpu as f64 + node_residual_ram as f64 / node_capacity_ram as f64) / 2.0).powi(3);

    let score = cpu_norm * ram_norm - imbalance_penalty * horizon_factor + next_job_fit_bonus - (cpu_penalty + ram_penalty) * balance_factor;
    score
}
